-- Schéma PostgreSQL équivalent. Les données de marché restent séparées.
CREATE TABLE clients (id varchar(64) PRIMARY KEY,name varchar(255) NOT NULL,client_type varchar(64) NOT NULL,country varchar(128),relationship_manager varchar(255),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE portfolios (id varchar(64) PRIMARY KEY,client_id varchar(64) NOT NULL REFERENCES clients(id) ON DELETE CASCADE,name varchar(255) NOT NULL,market varchar(32) NOT NULL,reference_currency varchar(8) NOT NULL,assets numeric(24,6) NOT NULL DEFAULT 0,performance numeric(12,6) NOT NULL DEFAULT 0,risk_level varchar(64),alerts integer NOT NULL DEFAULT 0,risk_profile varchar(64),profitability numeric(12,6) NOT NULL DEFAULT 0,entry_date date,status varchar(32) NOT NULL DEFAULT 'Actif',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE portfolio_allocations (portfolio_id varchar(64) REFERENCES portfolios(id) ON DELETE CASCADE,asset_class varchar(64),current_pct numeric(9,4),target_pct numeric(9,4),PRIMARY KEY(portfolio_id,asset_class));
CREATE TABLE currency_exposures (portfolio_id varchar(64) REFERENCES portfolios(id) ON DELETE CASCADE,currency varchar(8),weight_pct numeric(9,4),PRIMARY KEY(portfolio_id,currency));
CREATE TABLE cash_events (id varchar(64) PRIMARY KEY,portfolio_id varchar(64) REFERENCES portfolios(id) ON DELETE CASCADE,event_type varchar(32) NOT NULL,event_date date NOT NULL,amount numeric(24,6) NOT NULL,currency varchar(8) NOT NULL,label text,status varchar(32),source varchar(32),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE withdrawal_requests (id varchar(64) PRIMARY KEY,portfolio_id varchar(64) REFERENCES portfolios(id) ON DELETE CASCADE,amount numeric(24,6) NOT NULL,currency varchar(8) NOT NULL,status varchar(64) NOT NULL,requested_date date,desired_date date,relationship_manager varchar(255),observation text,payment_method varchar(64),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE manual_records (id bigserial PRIMARY KEY,module varchar(128) NOT NULL,record_key varchar(255),payload_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
